<?php require_once '../config/database.php';require_once '../includes/functions.php';if(admin()){header('Location: dashboard.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$pdo->prepare('SELECT * FROM admins WHERE username=?');$st->execute([$_POST['username']??'']);$a=$st->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];header('Location: dashboard.php');exit;}$error='Username atau password salah.';} ?><!doctype html><html lang="id"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Animo Label</title><style>body{font-family:Arial;background:#f2f2ef;display:grid;place-items:center;height:100vh}.box{background:#fff;padding:35px;border-radius:20px;width:min(400px,90%)}input,button{width:100%;padding:13px;margin:7px 0}button{background:#111;color:#fff;border:0;border-radius:8px}</style><div class="box"><h1>Animo Label</h1><p>Admin Login</p><?php if(isset($error))echo '<p>'.e($error).'</p>';?><form method="post"><input name="username" placeholder="Username" required><input name="password" type="password" placeholder="Password" required><button>Masuk</button></form></div>